pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        vm.assume(amount > 0);
        bound(amount, 1, 1 ether);

        // fund and deposit into c so the contract actually holds balance
        vm.deal(address(this), amount);
        (bool okDeposit,) = address(c).call{value: amount}("");
        assertTrue(okDeposit);

        uint256 balBefore = address(c).balance;
        assertTrue(balBefore == amount, "contract holds deposit");

        // a non-owner calls withdrawAll
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // RULE: withdrawAll must revert for non-owners and leave balance intact
        assertTrue(!ok && address(c).balance == balBefore, "non-owner cannot drain");
    }

    receive() external payable {}
}

