pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // accept the ether withdrawn by c.withdrawAll (owner is this contract)
    receive() external payable {}

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 100 ether);

        // an external party deposits fuzzed amount into c
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okIn, ) = address(c).call{value: amount}("");
        assertTrue(okIn);
        require(address(c).balance == amount, "setup failed");

        // owner (this contract, the deployer of c) drains everything
        vm.prank(address(this));
        c.withdrawAll();

        // GENERAL RULE: after withdrawAll, c holds no ether for ANY admissible input
        assertTrue(address(c).balance == 0);
    }
}

