pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 extra) public {
        amount = bound(amount, 1, type(uint256).max / 4);
        extra = bound(extra, 0, type(uint256).max / 4);
        uint256 fundAmount = amount + extra;
        // fund the contract through its receive() from the owner (test contract)
        vm.deal(address(this), fundAmount);
        (bool okFund, ) = payable(address(c)).call{value: fundAmount}("");
        assertTrue(okFund);
        uint256 ownerBalBefore = address(this).balance;
        uint256 cBalBefore = address(c).balance;
        // owner withdraws exactly `amount`
        c.withdraw(amount);
        // general rule: a successful withdraw(amount) pays out exactly `amount`:
        // the owner's balance grows by `amount` and the contract's balance shrinks by `amount`.
        assertTrue(
            address(this).balance == ownerBalBefore + amount &&
            address(c).balance == cBalBefore - amount
        );
    }
}

