    constructor(C _c) { c = _c; }
    function run(uint minAmount) public payable {
        require(c.owner() == address(this));
        require(address(c).balance >= minAmount);
        uint balBefore = address(this).balance;
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assert(!reverted && address(this).balance == balBefore + cBalBefore);
